CREATE DATABASE IF NOT EXISTS lake_boulevard CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE lake_boulevard;
CREATE TABLE rooms (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,description TEXT,price DECIMAL(10,2) NULL,image_url VARCHAR(500),active TINYINT(1) NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0);
CREATE TABLE bookings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,room_id INT UNSIGNED NULL,full_name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(50) NOT NULL,check_in DATE NOT NULL,check_out DATE NOT NULL,guests INT NOT NULL DEFAULT 2,status ENUM('pending','confirmed','cancelled') NOT NULL DEFAULT 'pending',message TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(room_id) REFERENCES rooms(id) ON DELETE SET NULL);
CREATE INDEX bookings_dates ON bookings(room_id,check_in,check_out,status);
CREATE TABLE booking_leads (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(50),check_in DATE,check_out DATE,guests INT,room_type VARCHAR(150),message TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE admin_users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE articles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,slug VARCHAR(255) NOT NULL UNIQUE,excerpt TEXT,content LONGTEXT NOT NULL,status ENUM('draft','published') NOT NULL DEFAULT 'draft',sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE menu_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,label VARCHAR(100) NOT NULL,url VARCHAR(500) NOT NULL,sort_order INT NOT NULL DEFAULT 0,visible TINYINT(1) NOT NULL DEFAULT 1,parent_id BIGINT UNSIGNED NULL);
